package com.example.rokidgeminisecretary;
import android.Manifest;import android.app.*;import org.json.*;
final class CalendarNavigationDialog {
 interface Selection{void select(JSONObject event);}
 static void show(Activity a,Selection selection){if(a.checkSelfPermission(Manifest.permission.READ_CALENDAR)!=0){new AlertDialog.Builder(a).setTitle("予定から目的地").setMessage("スマホに同期されたGoogleカレンダーを読み取り専用で参照します。選んだ場所は、経路検索の操作後に経路サービスへ送ります。").setPositiveButton("読み取りを許可",(d,w)->a.requestPermissions(new String[]{Manifest.permission.READ_CALENDAR},218)).setNegativeButton("戻る",null).show();return;}new AlertDialog.Builder(a).setTitle("予定の日付").setItems(new String[]{"今日","明日"},(d,i)->load(a,i,selection)).setNegativeButton("閉じる",null).show();}
 static void load(Activity a,int day,Selection selection){final boolean[] active={true};AlertDialog loading=new AlertDialog.Builder(a).setTitle("予定から目的地").setMessage("スマホの予定を確認中…").setNegativeButton("キャンセル",(d,w)->active[0]=false).setOnCancelListener(d->active[0]=false).create();loading.show();watch(a,loading,active,()->load(a,day,selection));new Thread(()->{JSONObject result;try{result=CalendarNavigation.response(a,day);}catch(Exception e){result=new JSONObject();}final JSONObject out=result;a.runOnUiThread(()->{if(!active[0]||a.isFinishing()||a.isDestroyed())return;active[0]=false;loading.dismiss();JSONArray items=out.optJSONArray("items");if(items==null||items.length()==0){new AlertDialog.Builder(a).setTitle("予定から目的地").setMessage(out.optString("message","取得できませんでした" )).setPositiveButton("選び直す",(d,w)->show(a,selection)).setNegativeButton("閉じる",null).show();return;}String[] labels=new String[items.length()];for(int i=0;i<labels.length;i++)labels[i]=items.optJSONObject(i).optString("label");new AlertDialog.Builder(a).setTitle((day==0?"今日":"明日")+"の予定"+(out.optBoolean("truncated")?"（先頭60件）":"")).setItems(labels,(d,k)->{JSONObject e=items.optJSONObject(k);if(!e.optBoolean("available")||!CalendarNavigation.fresh(out,System.currentTimeMillis())){new AlertDialog.Builder(a).setMessage(e.optBoolean("available")?"予定一覧の期限が切れました。選び直してください":e.optString("reason")).setPositiveButton("選び直す",(x,y)->load(a,day,selection)).setNegativeButton("閉じる",null).show();return;}if(CalendarLocationPolicy.explicit(e.optString("location"))){resolve(a,e.optString("token"),day,selection);return;}new AlertDialog.Builder(a).setTitle("予定の場所を確認").setMessage(CalendarNavigation.label(e)+"\n今から出発する経路を検索します。予定の開始時刻への到着を保証するものではありません。").setPositiveButton("目的地にセット",(x,y)->{resolve(a,e.optString("token"),day,selection);}).setNegativeButton("戻る",(x,y)->load(a,day,selection)).show();}).setNeutralButton("日付を変更",(d,w)->show(a,selection)).setNegativeButton("閉じる",null).show();});},"CalendarNavigationRead").start();}
 static void resolve(Activity a,String token,int day,Selection selection){final boolean[] active={true};AlertDialog wait=new AlertDialog.Builder(a).setTitle("予定の変更を確認中").setMessage("場所・日時を再確認しています…").setNegativeButton("キャンセル",(d,w)->active[0]=false).setOnCancelListener(d->active[0]=false).create();wait.show();watch(a,wait,active,()->load(a,day,selection));new Thread(()->{JSONObject result;try{result=CalendarNavigation.resolve(a,token);}catch(Exception ex){result=new JSONObject();}JSONObject out=result;a.runOnUiThread(()->{if(!active[0]||a.isFinishing()||a.isDestroyed())return;wait.dismiss();if(out.optString("status").equals("selected"))selection.select(out.optJSONObject("item"));else new AlertDialog.Builder(a).setMessage(out.optString("message","予定を確認できません。選び直してください")).setPositiveButton("選び直す",(d,w)->load(a,day,selection)).setNegativeButton("閉じる",null).show();});},"CalendarNavigationValidate").start();}
 static void watch(Activity a,AlertDialog dialog,boolean[] active,Runnable retry){android.os.Handler h=new android.os.Handler(android.os.Looper.getMainLooper());Runnable timeout=()->{if(!active[0])return;active[0]=false;dialog.dismiss();if(!a.isFinishing()&&!a.isDestroyed())new AlertDialog.Builder(a).setTitle("予定の取得が時間切れです").setMessage("カレンダーの同期・権限を確認し、選び直してください。案内は開始していません。").setPositiveButton("選び直す",(d,w)->retry.run()).setNegativeButton("閉じる",null).show();};dialog.setOnDismissListener(d->{active[0]=false;h.removeCallbacks(timeout);});h.postDelayed(timeout,12000);}
 private CalendarNavigationDialog(){}
}
